package com.quicknotes.app;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
public class Reminders extends BroadcastReceiver {
 static final String PREFS="alarm-state";
 static PendingIntent alarm(Context c,String id,long expected){return PendingIntent.getBroadcast(c,0,new Intent(c,Reminders.class).setAction("reminder:"+id).putExtra("id",id).putExtra("expectedDue",expected),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static JSONObject read(Context c)throws Exception{try(InputStream in=new FileInputStream(new File(c.getFilesDir(),"data.json"))){return MainActivity.validate(new JSONObject(new String(MainActivity.bytes(in,MainActivity.MAX_BUNDLE),"UTF-8")));}}
 static void write(Context c,JSONObject d)throws Exception{File temp=new File(c.getFilesDir(),"alarm-data.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(d.toString().getBytes("UTF-8"));out.getFD().sync();}if(!temp.renameTo(new File(c.getFilesDir(),"data.json")))throw new IOException("Cannot save reminder state");}
 static boolean exactAllowed(Context c){return Build.VERSION.SDK_INT<31||((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).canScheduleExactAlarms();}
 static boolean activeList(JSONObject d,String id)throws Exception{JSONArray lists=d.getJSONArray("lists");for(int n=0;n<lists.length();n++){JSONObject l=lists.getJSONObject(n);if(id.equals(l.optString("id"))&&!l.optBoolean("deleted"))return true;}return false;}
 static long scheduledDue(JSONObject i){return i.optBoolean("done")&&i.optString("repeat").length()>0?i.optLong("nextDue"):!i.optBoolean("done")?i.optLong("due"):0;}
 static JSONObject find(JSONObject d,String id)throws Exception{JSONArray a=d.getJSONArray("items");for(int n=0;n<a.length();n++)if(id.equals(a.getJSONObject(n).getString("id")))return a.getJSONObject(n);return null;}
 static boolean reactivate(JSONObject d,long now)throws Exception{boolean changed=false;JSONArray a=d.getJSONArray("items");for(int n=0;n<a.length();n++){JSONObject i=a.getJSONObject(n);if(!i.optBoolean("deleted")&&i.optBoolean("done")&&!i.optString("repeat").isEmpty()&&i.optLong("nextDue")>0&&i.optLong("nextDue")<=now&&activeList(d,i.optString("list"))){i.put("due",i.getLong("nextDue")).put("nextDue",0).put("done",false).put("updated",Math.max(now,i.optLong("updated")+1));for(int k=0;k<a.length();k++){JSONObject child=a.getJSONObject(k);if(i.getString("id").equals(child.optString("parent"))&&!child.optBoolean("deleted"))child.put("done",false).put("updated",Math.max(now,child.optLong("updated")+1));}changed=true;}}return changed;}
 static void schedule(Context c,JSONObject d)throws Exception{
  AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray items=d.getJSONArray("items");SharedPreferences prefs=c.getSharedPreferences(PREFS,0);long now=System.currentTimeMillis();
  for(int n=0;n<items.length();n++){JSONObject i=items.getJSONObject(n);String id=i.getString("id");long due=scheduledDue(i);PendingIntent pi=alarm(c,id,due);am.cancel(pi);
   boolean active=!i.optBoolean("deleted")&&activeList(d,i.optString("list"));long snooze=prefs.getLong("snooze:"+id,0);long snoozeDue=prefs.getLong("snooze-due:"+id,0);if(snooze>now&&snoozeDue==due&&active&&!i.optBoolean("done"))due=snooze;else if(snooze>0)prefs.edit().remove("snooze:"+id).remove("snooze-due:"+id).apply();
   if(active&&due>now){if(i.optBoolean("urgent")&&i.optBoolean("timeEnabled",true)){if(exactAllowed(c)&&((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled()){PendingIntent show=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(new AlarmManager.AlarmClockInfo(due,show),pi);}}else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);}
  }
  AlarmService.reconcile(c,d);
 }
 @Override public void onReceive(Context c,Intent intent){PendingResult pending=goAsync();new Thread(()->{try{synchronized(MainActivity.STORE_LOCK){JSONObject d=read(c);String action=intent.getAction();if(Intent.ACTION_BOOT_COMPLETED.equals(action)||Intent.ACTION_TIME_CHANGED.equals(action)||Intent.ACTION_TIMEZONE_CHANGED.equals(action)||AlarmManager.ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED.equals(action)){if(reactivate(d,System.currentTimeMillis()))write(c,d);schedule(c,d);return;}
  String id=intent.getStringExtra("id");JSONObject item=find(d,id);if(item==null||item.optBoolean("deleted")||!activeList(d,item.optString("list")))return;
  long expected=intent.getLongExtra("expectedDue",-1),due=scheduledDue(item);if(expected!=due)return;long snooze=c.getSharedPreferences(PREFS,0).getLong("snooze:"+id,0);if(snooze>System.currentTimeMillis()+2000)return;if(due>System.currentTimeMillis()+2000)return;
  if(item.optBoolean("done")){if(item.optLong("nextDue")==0)return;reactivate(d,System.currentTimeMillis()+1000);write(c,d);item=find(d,id);if(item.optBoolean("done"))return;}
  c.getSharedPreferences(PREFS,0).edit().remove("snooze:"+id).remove("snooze-due:"+id).apply();
  if(item.optBoolean("urgent")&&item.optBoolean("timeEnabled",true)){Intent ring=new Intent(c,AlarmService.class).setAction("RING").putExtra("id",id).putExtra("expectedDue",item.optLong("due"));try{c.startForegroundService(ring);}catch(Exception e){notifyReminder(c,item);}}else notifyReminder(c,item);
 }}catch(Exception e){android.util.Log.e("QuickNotes","Reminder delivery failed",e);}finally{pending.finish();}},"quicknotes-delivery").start();}
 static void notifyReminder(Context c,JSONObject item)throws Exception{NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("reminders","Reminder alerts",NotificationManager.IMPORTANCE_HIGH));String id=item.getString("id");PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(id,id.hashCode(),new Notification.Builder(c,"reminders").setSmallIcon(R.drawable.ic_notification).setContentTitle(item.optString("title")).setContentText(item.optString("notes","Reminder due")).setContentIntent(open).setAutoCancel(true).build());}
}
